// Turns the posted positions into the rows that will replace the `portfel` table.
//
// Two rules decide the shape of this node:
//   1. NOTATKI SĄ ŚWIĘTE. The CSV from the broker knows quantities and prices; it does not
//      know why you bought. Notes are read from the current table and re-attached by
//      ticker, so an import never silently erases the only human input in the system.
//   2. A BROKEN IMPORT MUST NOT WIPE THE PORTFOLIO. Zero valid rows throws instead of
//      clearing the table — a mis-parsed CSV would otherwise look exactly like "I sold
//      everything". Selling everything is expressed explicitly with force=true.
const body = $('Webhook').first().json.body || {};
const przyslane = Array.isArray(body.pozycje) ? body.pozycje : [];
const force = body.force === true || body.force === 'true';

let biezace = [];
try { biezace = $('Read current').all().map((i) => i.json).filter((w) => w && w.ticker); } catch (e) { biezace = []; }
const notatki = {};
for (const w of biezace) { notatki[String(w.ticker).toUpperCase()] = String(w.notatka || ''); }

const rows = [];
const odrzucone = [];
for (const p of przyslane) {
  const ticker = String((p && p.ticker) || '').trim().toUpperCase();
  const szt = Number(p && p.szt);
  const cena = Number(p && p.cena_kupna);
  if (!ticker || !Number.isFinite(szt) || szt <= 0 || !Number.isFinite(cena) || cena <= 0) {
    odrzucone.push(JSON.stringify(p));
    continue;
  }
  // A note sent explicitly wins; otherwise the one already in the table survives.
  const notatka = String((p && p.notatka) || '').trim() || notatki[ticker] || '';
  rows.push({ ticker, szt, cena_kupna: cena, data: String((p && p.data) || '').trim(), notatka });
}

if (!rows.length && !force) {
  throw new Error(
    `Zero poprawnych pozycji w żądaniu (odrzucone: ${odrzucone.length}). Tabela NIE została ruszona. ` +
    'Jeśli naprawdę chcesz wyczyścić portfel, wyślij {"pozycje": [], "force": true}.',
  );
}

const zachowane = rows.filter((r) => r.notatka && notatki[r.ticker] === r.notatka).map((r) => r.ticker);
const nowe = rows.filter((r) => !(r.ticker in notatki)).map((r) => r.ticker);
const zniknely = Object.keys(notatki).filter((t) => !rows.some((r) => r.ticker === t));

return [{ json: { rows, podsumowanie: { wierszy: rows.length, odrzuconych: odrzucone.length, odrzucone, zachowane_notatki: zachowane, nowe_pozycje: nowe, znikniete_pozycje: zniknely } } }];

// One item per row — the insert node writes one row per input item.
// Rows come from `Prepare rows`, not from $json: the upstream node here is
// `Clear table`, whose output is its own {success: ...} report.
return ($('Prepare rows').first().json.rows || []).map((r) => ({ json: r }));

// Response for the caller: what landed and which notes survived.
const p = $('Prepare rows').first().json.podsumowanie;
return [{ json: { ok: true, ...p } }];
